<script setup lang="ts">import { computed } from 'vue'; import { NCard, NProgress } from 'naive-ui'; const props = defineProps<{ values: Record<string, number> }>(); const rows = computed(() => Object.entries(props.values).sort((a,b)=>b[1]-a[1])); const max = computed(() => Math.max(1, ...rows.value.map(([,value])=>value)))</script>
<template><NCard title="Token 用量" size="small"><div class="chart-row" v-for="([agent,value]) in rows" :key="agent"><span>{{ agent }}</span><NProgress type="line" :percentage="Math.round(value / max * 100)" :show-indicator="false" /><strong>{{ value.toLocaleString() }}</strong></div><div v-if="!rows.length" class="empty">暂无数据</div></NCard></template>
<style scoped>.chart-row{display:grid;grid-template-columns:90px 1fr 72px;gap:8px;align-items:center;margin:10px 0;font-size:12px}.chart-row span{text-transform:capitalize}.chart-row strong{text-align:right;font-variant-numeric:tabular-nums}.empty{color:var(--text-muted);font-size:12px}</style>
